    }
    time = System.currentTimeMillis();
    for (int i = 0; i < insertCnt; ) {
        for (int j = 0; j < batchSize; j++) {
            adminStmt.addBatch("INSERT INTO root.a(timestamp, b0) VALUES (" + (i++ + 1 + insertCnt) + ", 100)");
