        adminStmt.clearBatch();
    }
    if (logger.isInfoEnabled()) {
        logger.info("User inserted {} data points used {} ms with {} privileges.", insertCnt, System.currentTimeMillis() - time, privilegeCnt);
    }
    adminCon.close();
    userCon.close();
}

