@Test
public void testFlushGivenGroup() throws ClassNotFoundException {
    Class.forName(Config.JDBC_DRIVER_NAME);
    IoTDBDescriptor.getInstance().getConfig().setAutoCreateSchemaEnabled(true);
    String insertTemplate = "INSERT INTO root.group%d(timestamp, s1, s2, s3) VALUES (%d, %d, %f, %s)";
    try (Connection connection = DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        statement.execute("SET STORAGE GROUP TO root.group1");
        statement.execute("SET STORAGE GROUP TO root.group2");
        statement.execute("SET STORAGE GROUP TO root.group3");
        for (int i = 1; i <= 3; i++) {
            for (int j = 10; j < 20; j++) {
                statement.execute(String.format(insertTemplate, i, j, j, j * 0.1, String.valueOf(j)));
            }
        }
        statement.execute("FLUSH");
        for (int i = 1; i <= 3; i++) {
            for (int j = 0; j < 10; j++) {
                statement.execute(String.format(insertTemplate, i, j, j, j * 0.1, String.valueOf(j)));
            }
        }
        statement.execute("FLUSH root.group1");
        statement.execute("FLUSH root.group2,root.group3");
        for (int i = 1; i <= 3; i++) {
            for (int j = 0; j < 30; j++) {
                statement.execute(String.format(insertTemplate, i, j, j, j * 0.1, String.valueOf(j)));
            }
        }
        statement.execute("FLUSH root.group1 true");
        statement.execute("FLUSH root.group2,root.group3 false");
        ResultSet resultSet = statement.executeQuery("SELECT * from root.group1,root.group2,root" + ".group3");
        int i = 0;
        while (resultSet.next()) {
            i++;
        }
        assertEquals(30, i);
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    } finally {
        IoTDBDescriptor.getInstance().getConfig().setAutoCreateSchemaEnabled(false);
    }
}

