 * values(2018-1-1T13:00:09+08:00,12) insert into root.timezone(timestamp,tz1) values(2018-1-1T12:00:10+07:00,13)
 *
 * select * from root
 */
@Test
public void timezoneTest() throws ClassNotFoundException, SQLException, TException {
    Class.forName(Config.JDBC_DRIVER_NAME);
    try (IoTDBConnection connection = (IoTDBConnection) DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        String insertSQLTemplate = "insert into root.timezone(timestamp,tz1) values(%s,%s)";
        connection.setTimeZone("+08:00");
        // 1514779200000 = 2018-1-1T12:00:00+08:00
        statement.execute(String.format(insertSQLTemplate, "1514779200000", "1"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:01", "2"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:02+08:00", "3"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:03+09:00", "4"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:04+07:00", "5"));
        connection.setTimeZone("+09:00");
        statement.execute(String.format(insertSQLTemplate, "1514789200000", "6"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T14:00:05", "7"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:03+08:00", "8"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:06+07:00", "9"));
        // Asia/Almaty +06:00
        connection.setTimeZone("Asia/Almaty");
        statement.execute(String.format(insertSQLTemplate, "1514782807000", "10"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T11:00:08", "11"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T13:00:09+08:00", "12"));
        statement.execute(String.format(insertSQLTemplate, "2018-1-1T12:00:10+07:00", "13"));
        boolean hasResultSet = statement.execute("select * from root");
        Assert.assertTrue(hasResultSet);
        ResultSet resultSet = statement.getResultSet();
        int cnt = 0;
        while (resultSet.next()) {
            String ans = resultSet.getString(TIMESTAMP_STR) + "," + resultSet.getString(tz1);
            Assert.assertEquals(retArray[cnt], ans);
            cnt++;
        }
        Assert.assertEquals(13, cnt);
    }
}

@Test
public void testTTL() throws SQLException {
    try (IoTDBConnection connection = (IoTDBConnection) DriverManager.getConnection(Config.IOTDB_URL_PREFIX + "127.0.0.1:6667/", "root", "root");
        Statement statement = connection.createStatement()) {
        try {
            statement.execute("SET TTL TO root.TTL_SG1 1000");
        } catch (SQLException e) {
            assertEquals(TSStatusCode.PATH_ERROR.getStatusCode(), e.getErrorCode());
        }
        try {
            statement.execute("UNSET TTL TO root.TTL_SG1");
        } catch (SQLException e) {
            assertEquals(TSStatusCode.PATH_ERROR.getStatusCode(), e.getErrorCode());
        }
        statement.execute("SET STORAGE GROUP TO root.TTL_SG1");
        statement.execute("CREATE TIMESERIES root.TTL_SG1.s1 WITH DATATYPE=INT64,ENCODING=PLAIN");
        try {
            statement.execute("SET TTL TO root.TTL_SG1.s1 1000");
        } catch (SQLException e) {
            assertEquals(TSStatusCode.NOT_STORAGE_GROUP_ERROR.getStatusCode(), e.getErrorCode());
        }
        long now = System.currentTimeMillis();
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 100 + i, i));
        }
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 100000 + i, i));
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(200, cnt);
        }
        statement.execute("SET TTL TO root.TTL_SG1 10000");
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(100, cnt);
        }
        for (int i = 0; i < 100; i++) {
            boolean caught = false;
            try {
                statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 50000 + i, i));
            } catch (SQLException e) {
                if (TSStatusCode.OUT_OF_TTL_ERROR.getStatusCode() == e.getErrorCode()) {
                    caught = true;
                }
            }
            assertTrue(caught);
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertEquals(100, cnt);
        }
        statement.execute("UNSET TTL TO root.TTL_SG1");
        for (int i = 0; i < 100; i++) {
            statement.execute(String.format("INSERT INTO root.TTL_SG1(timestamp, s1) VALUES (%d, %d)", now - 30000 + i, i));
        }
        try (ResultSet resultSet = statement.executeQuery("SELECT s1 FROM root.TTL_SG1")) {
            int cnt = 0;
            while (resultSet.next()) {
                cnt++;
            }
            assertTrue(cnt >= 200);
        }
    }
}

