    } catch (StorageGroupException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        root.setStorageGroup("root.laptop.d2");
    } catch (StorageGroupException e) {
        fail(e.getMessage());
    }
    try {
        root.setStorageGroup("root.laptop");
    } catch (StorageGroupException e) {
        Assert.assertEquals("The seriesPath of [root.laptop] already exist, it can't be set to the storage group", e.getMessage());
    }
    // check timeseries
    assertFalse(root.isPathExist("root.laptop.d1.s0"));
    assertFalse(root.isPathExist("root.laptop.d1.s1"));
    assertFalse(root.isPathExist("root.laptop.d2.s0"));
    assertFalse(root.isPathExist("root.laptop.d2.s1"));
    try {
        assertEquals("root.laptop.d1", root.getStorageGroupNameByPath("root.laptop.d1.s0"));
        root.addTimeseriesPath("root.laptop.d1.s0", TSDataType.INT32, TSEncoding.RLE, CompressionType.valueOf(TSFileDescriptor.getInstance().getConfig().getCompressor()), Collections.EMPTY_MAP);
        assertEquals("root.laptop.d1", root.getStorageGroupNameByPath("root.laptop.d1.s1"));
        root.addTimeseriesPath("root.laptop.d1.s1", TSDataType.INT32, TSEncoding.RLE, CompressionType.valueOf(TSFileDescriptor.getInstance().getConfig().getCompressor()), Collections.EMPTY_MAP);
        assertEquals("root.laptop.d2", root.getStorageGroupNameByPath("root.laptop.d2.s0"));
        root.addTimeseriesPath("root.laptop.d2.s0", TSDataType.INT32, TSEncoding.RLE, CompressionType.valueOf(TSFileDescriptor.getInstance().getConfig().getCompressor()), Collections.EMPTY_MAP);
        assertEquals("root.laptop.d2", root.getStorageGroupNameByPath("root.laptop.d2.s1"));
        root.addTimeseriesPath("root.laptop.d2.s1", TSDataType.INT32, TSEncoding.RLE, CompressionType.valueOf(TSFileDescriptor.getInstance().getConfig().getCompressor()), Collections.EMPTY_MAP);
    } catch (PathException | StorageGroupException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    try {
        root.deletePath("root.laptop.d1.s0");
    } catch (PathException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    assertFalse(root.isPathExist("root.laptop.d1.s0"));
    try {
        root.deletePath("root.laptop.d1");
    } catch (PathException e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
    assertFalse(root.isPathExist("root.laptop.d1.s1"));
    assertFalse(root.isPathExist("root.laptop.d1"));
    assertTrue(root.isPathExist("root.laptop"));
    assertTrue(root.isPathExist("root.laptop.d2"));
    assertTrue(root.isPathExist("root.laptop.d2.s0"));
}

