@Test
public void aggregateTest() {
    try {
        Path path = new Path(SERIES_READER_TEST_SG + PATH_SEPARATOR + "device0", "sensor0");
        QueryDataSource queryDataSource = new QueryDataSource(path, seqResources, unseqResources);
        SeriesAggregateReader seriesReader = new SeriesAggregateReader(path, TSDataType.INT32, new QueryContext(), queryDataSource, null, null);
        AggregateResult aggregateResult = AggreResultFactory.getAggrResultByName("count", TSDataType.INT32);
        while (seriesReader.hasNextChunk()) {
            if (seriesReader.canUseCurrentChunkStatistics()) {
                Statistics chunkStatistics = seriesReader.currentChunkStatistics();
                aggregateResult.updateResultFromStatistics(chunkStatistics);
                seriesReader.skipCurrentChunk();
                continue;
            }
            int loopTime = 0;
            while (seriesReader.hasNextPage()) {
                if (seriesReader.canUseCurrentPageStatistics()) {
                    Statistics pageStatistic = seriesReader.currentPageStatistics();
                    if (loopTime == 0) {
                        assertEquals(260, pageStatistic.getStartTime());
                        assertEquals(279, pageStatistic.getEndTime());
                    } else if (loopTime == 1) {
                        assertEquals(280, pageStatistic.getStartTime());
                        assertEquals(299, pageStatistic.getEndTime());
                    } else {
                        assertEquals(380, pageStatistic.getStartTime());
                        assertEquals(399, pageStatistic.getEndTime());
                    }
                    assertEquals(20, pageStatistic.getCount());
                    aggregateResult.updateResultFromStatistics(pageStatistic);
                    seriesReader.skipCurrentPage();
                    continue;
                }
                while (seriesReader.hasNextOverlappedPage()) {
                    BatchData nextOverlappedPageData = seriesReader.nextOverlappedPage();
                    aggregateResult.updateResultFromPageData(nextOverlappedPageData);
                    nextOverlappedPageData.resetBatchData();
                    assertEquals(true, nextOverlappedPageData.hasCurrent());
                }
                loopTime++;
            }
        }
        assertEquals(500L, aggregateResult.getResult());
    } catch (IOException | QueryProcessException e) {
        e.printStackTrace();
        fail();
    }
}

@Test
public void test() throws IOException {
    QueryDataSource dataSource = new QueryDataSource(new Path(SERIES_READER_TEST_SG + PATH_SEPARATOR + "device0", "sensor0"), seqResources, unseqResources);
    SeriesReaderByTimestamp seriesReader = new SeriesReaderByTimestamp(new Path(SERIES_READER_TEST_SG + PATH_SEPARATOR + "device0", "sensor0"), TSDataType.INT32, new QueryContext(), dataSource);
    for (int time = 0; time < 500; time++) {
        Integer value = (Integer) seriesReader.getValueInTimestamp(time);
        if (time < 200) {
            Assert.assertEquals(time + 20000, value.intValue());
        } else if (time < 260 || (time >= 300 && time < 380) || (time >= 400)) {
            Assert.assertEquals(time + 10000, value.intValue());
        } else {
            Assert.assertEquals(time, value.intValue());
        }
    }
}

